  'stamm.canvas_leer2': { de: 'Suchen Sie links ein Mitglied und holen Sie es mit + ins Bild. Danach anklicken und Eltern, Partner, Geschwister oder Kinder hinzufügen.', en: 'Search a member on the left and add it with +. Then click it and add parents, partner, siblings or children.', sq: 'Kërkoni majtas një anëtar dhe shtojeni me +. Pastaj klikojeni dhe shtoni prindër, partner, vëllezër/motra ose fëmijë.' },
  'stamm.person_anklicken': { de: 'Person im Baum anklicken, um Verwandte hinzuzufügen oder Beziehungen zu lösen.', en: 'Click a person in the tree to add relatives or remove relations.', sq: 'Klikoni një person në pemë për të shtuar të afërm ose hequr lidhje.' },
  'stamm.familie_suchen': { de: 'Familie oder Person suchen …', en: 'Search family or person …', sq: 'Kërko familje ose person …' },
  'stamm.leer2': { de: 'Eine Familie entsteht, sobald zwei Mitglieder als Eltern, Kind, Partner oder Geschwister verbunden sind — hier über »Neue Familie« oder direkt beim Mitglied im Reiter »Familie«.', en: 'A family appears as soon as two members are linked as parent, child, partner or sibling — here via »New family« or directly in the member’s »Family« tab.', sq: 'Një familje shfaqet sapo dy anëtarë lidhen si prind, fëmijë, partner ose vëlla/motër — këtu me »Familje e re« ose direkt te anëtari në skedën »Familja«.' },
  'stamm.nicht_gefunden': { de: 'Dieses Mitglied ist im Stammbaum nicht sichtbar.', en: 'This member is not visible in the family tree.', sq: 'Ky anëtar nuk duket në pemën familjare.' },
  'stamm.keine_familie': { de: 'Noch keiner Familie zugeordnet', en: 'Not part of a family yet', sq: 'Ende pa familje' },
  'stamm.keine_familie_hinweis': { de: 'Unten Eltern, Partner, Geschwister oder Kinder hinzufügen — daraus entsteht der Stammbaum.', en: 'Add parents, partner, siblings or children below — the family tree builds from that.', sq: 'Shtoni më poshtë prindër, partner, vëllezër/motra ose fëmijë — prej tyre ndërtohet pema.' },
  'stamm.im_stammbaum': { de: 'Im Stammbaum öffnen', en: 'Open in family tree', sq: 'Hape në pemë' },
  'stamm.name_fehlt': { de: 'Noch nicht benannt — klicken zum Benennen', en: 'Not named yet — click to name', sq: 'Ende pa emër — klikoni për ta emërtuar' },
  'plat.bild1_marke': { de: 'Mitgliederverzeichnis', en: 'Member register', sq: 'Regjistri i anëtarëve' },
  'plat.bild1_titel': { de: 'Wer dabei ist, und wer bezahlt hat.', en: 'Who is a member, and who has paid.', sq: 'Kush është anëtar dhe kush ka paguar.' },
  'plat.bild1_text': { de: 'Jedes Mitglied mit Nachbarschaft, Beitrag und Zahlstatus. Filtern, suchen, als Liste ausgeben — und sehen, wo Angaben fehlen.', en: 'Every member with neighbourhood, fee and payment status. Filter, search, export — and see where details are missing.', sq: 'Çdo anëtar me lagjen, kuotën dhe statusin e pagesës. Filtroni, kërkoni, eksportoni — dhe shihni ku mungojnë të dhënat.' },
  'plat.bild2_marke': { de: 'Swiss QR-Rechnung', en: 'Swiss QR invoice', sq: 'Faturë Swiss QR' },
  'plat.bild2_titel': { de: 'Eine Rechnung, die jede Bank liest.', en: 'An invoice every bank reads.', sq: 'Një faturë që e lexon çdo bankë.' },
  'plat.bild2_text': { de: 'Mit Referenznummer je Mitglied — die Zahlung lässt sich automatisch zuordnen. Zum Drucken oder als E-Mail.', en: 'With a reference number per member, so payments reconcile themselves. To print or send by email.', sq: 'Me numër reference për çdo anëtar — pagesa njihet vetvetiu. Për shtyp ose me email.' },
  'plat.bild3_marke': { de: 'Stammbaum', en: 'Family tree', sq: 'Pema familjare' },
  'plat.bild3_titel': { de: 'Familien, nicht nur Einzelpersonen.', en: 'Families, not just individuals.', sq: 'Familje, jo vetëm individë.' },
  'plat.bild3_text': { de: 'Eltern, Partner und Geschwister erfassen — Cousins, Onkel und Grosseltern ergeben sich daraus von selbst.', en: 'Record parents, partners and siblings — cousins, uncles and grandparents follow by themselves.', sq: 'Regjistroni prindërit, partnerët dhe vëllezërit — kushërinjtë, dajallarët dhe gjyshërit dalin vetvetiu.' },
  // Postversand auf der Betreiberseite. Ohne Anbietername: wer den Druck
  // besorgt, ist fuer den Verein so wenig von Belang wie der Name der
  // Druckerei auf einer Rechnung -- und ein Name, der auf der
  // Landingpage steht, muss dort auch stehen bleiben, wenn der Anbieter
  // einmal wechselt.
  'plat.bild4_marke': { en: 'Letters', de: 'Postversand', sq: 'Dërgimi me postë' },
  'plat.bild4_titel': { en: 'Also the ones without email.', de: 'Auch die, die keine E-Mail haben.', sq: 'Edhe ata pa email.' },
  'plat.bild4_text': { en: 'Members without an email address get their bill as a letter — printed, enveloped and stamped, without anyone in the association doing it by hand. And what became of it comes back: in transit, delivered, or undeliverable. A bookable module with a quota of letters.', de: 'Mitglieder ohne E-Mail-Adresse bekommen ihre Rechnung als Brief — gedruckt, kuvertiert und frankiert, ohne dass jemand im Verein das von Hand macht. Und es kommt zurück, was daraus geworden ist: unterwegs, zugestellt oder nicht zustellbar. Zubuchbares Modul mit einem Kontingent an Briefen.', sq: 'Anëtarët pa adresë emaili e marrin faturën si letër — e shtypur, në zarf dhe me pullë, pa që ndonjë në shoqatë ta bëjë me dorë. Dhe kthehet çfarë u bë me të: në rrugë, e dorëzuar ose e padorëzueshme. Modul i zgjedhshëm me një kuotë letrash.' },
