  'samod.hinweis': { de: 'Leeres Preisfeld heisst »im Grundpreis enthalten«. Welche Vereine ein Modul haben, schalten Sie beim jeweiligen Verein unter »Verwalten«.', en: 'An empty price field means »included in the base price«. Which associations have a module is set per association under »Manage«.', sq: 'Fusha bosh e çmimit do të thotë »përfshirë në çmimin bazë«. Se cilat shoqata e kanë një modul, caktohet te secila shoqatë nën »Menaxho«.' },
  'spende.marke': { de: 'Spenden', en: 'Donate', sq: 'Dhuro' },
  'spende.titel': { de: 'Ihre Spende kommt an.', en: 'Your donation gets there.', sq: 'Donacioni juaj mbërrin.' },
  'spende.intro': { de: 'Jeder Franken fliesst in die Vorhaben des Vereins. Sie erhalten einen Einzahlungsschein mit Referenznummer — damit ordnet sich Ihre Zahlung von selbst zu.', en: 'Every franc goes into the association\u2019s projects. You receive a payment slip with a reference number, so your payment reconciles itself.', sq: 'Çdo frang shkon në projektet e shoqatës. Merrni një fletëpagesë me numër reference — kështu pagesa juaj njihet vetvetiu.' },
