  'spende.anonym': { de: 'Anonym spenden (dann ohne Spendenbescheinigung)', en: 'Donate anonymously (no donation receipt then)', sq: 'Dhuro në mënyrë anonime (pa vërtetim donacioni)' },
  'spende.warum_adresse': { de: 'Name und Adresse brauchen wir nur für die Spendenbescheinigung — in der Schweiz sind Spenden an gemeinnützige Vereine abzugsfähig.', en: 'We need name and address only for the donation receipt — in Switzerland donations to charitable associations are tax-deductible.', sq: 'Emrin dhe adresën na duhen vetëm për vërtetimin e donacionit — në Zvicër donacionet për shoqata bamirëse zbriten nga tatimi.' },
