  'spende.weiter': { de: 'Einzahlungsschein erstellen', en: 'Create payment slip', sq: 'Krijo fletëpagesën' },
  'spende.hinweis_qr': { de: 'Sie zahlen anschliessend selbst — per E-Banking, TWINT oder am Schalter. Es wird nichts abgebucht.', en: 'You pay afterwards yourself — by e-banking, TWINT or at the counter. Nothing is debited.', sq: 'Paguani më pas vetë — me e-banking, TWINT ose në sportel. Asgjë nuk tërhiqet automatikisht.' },
