  'zl.nur_mitglieder': { de: 'Diese Übersicht sehen nur Mitglieder. Bitte melden Sie sich an.', en: 'Only members can see this overview. Please sign in.', sq: 'Këtë pasqyrë e shohin vetëm anëtarët. Ju lutem identifikohuni.' },
  'zl.widerspruch_hinweis': { de: 'Wer nicht namentlich erscheinen möchte, kann das im eigenen Profil einstellen. Gezählt wird er trotzdem.', en: 'Anyone who prefers not to be named can set this in their profile. They are still counted.', sq: 'Kush nuk dëshiron të shfaqet me emër, mund ta caktojë këtë në profilin e vet. Megjithatë numërohet.' },
  'zl.admin_titel': { de: 'Zahlerliste und Nachbarschaften', en: 'Payer list and neighbourhoods', sq: 'Lista e paguesve dhe lagjet' },
  'zl.admin_hinweis': { de: 'Eine eigene Seite zeigt, wie viele den Beitrag bezahlt haben, auf Wunsch je Nachbarschaft und mit Namen. Wer im Profil widersprochen hat, erscheint nie mit Namen.', en: 'A separate page shows how many have paid, optionally per neighbourhood and by name. Members who opted out never appear by name.', sq: 'Një faqe e veçantë tregon sa kanë paguar, sipas dëshirës për çdo lagje dhe me emra. Kush ka kundërshtuar në profil nuk shfaqet kurrë me emër.' },
