  'benach.alle_gelesen': { de: 'Alle gelesen', en: 'Mark all read', sq: 'Të gjitha të lexuara' },
  'benach.leer': { de: 'Noch nichts Neues. Rechnungen, Veranstaltungen und Neuigkeiten erscheinen hier.', en: 'Nothing new yet. Invoices, events and news will show up here.', sq: 'Ende asgjë e re. Faturat, ngjarjet dhe lajmet shfaqen këtu.' },
  'push.frage': { de: 'Auch aufs Handy, wenn die App zu ist?', en: 'Also on your phone when the app is closed?', sq: 'Edhe në telefon kur aplikacioni është i mbyllur?' },
  'push.einschalten': { de: 'Einschalten', en: 'Turn on', sq: 'Aktivizo' },
  'push.ausschalten': { de: 'Ausschalten', en: 'Turn off', sq: 'Çaktivizo' },
  'push.an': { de: 'Neues kommt auf dieses Gerät, auch wenn die App zu ist.', en: 'News reaches this device even when the app is closed.', sq: 'Të rejat vijnë në këtë pajisje edhe kur aplikacioni është i mbyllur.' },
  'push.ios': { de: 'Für Nachrichten aufs iPhone: zuerst die App installieren (Teilen → Zum Home-Bildschirm), dann hier einschalten.', en: 'For notifications on iPhone: install the app first (Share → Add to Home Screen), then turn them on here.', sq: 'Për njoftime në iPhone: instalo së pari aplikacionin (Ndaj → Shto në ekranin kryesor), pastaj aktivizo këtu.' },
  'push.verweigert': { de: 'Nachrichten sind für diese Seite blockiert. Freigeben lässt es sich in den Einstellungen des Browsers.', en: 'Notifications are blocked for this site. You can allow them in your browser settings.', sq: 'Njoftimet janë bllokuar për këtë faqe. Mund t’i lejosh te cilësimet e shfletuesit.' },
