  'social.vorgemerkt': { en: 'Post scheduled. Nothing has been sent yet.', de: 'Beitrag vorgemerkt. Gesendet wird noch nichts.', sq: 'Postimi u planifikua. Ende nuk dërgohet asgjë.' },
