  'social.seite_waehlen': { en: 'Which page belongs to the association?', de: 'Welche Seite gehört dem Verein?', sq: 'Cila faqe i përket shoqatës?' },
  'social.seite_waehlen_text': { en: 'Your Facebook account administers several pages. Pick the one the association posts from.', de: 'Ihr Facebook-Konto verwaltet mehrere Seiten. Wählen Sie die, von der aus der Verein postet.', sq: 'Llogaria juaj në Facebook administron disa faqe. Zgjidhni atë nga e cila poston shoqata.' },
  'social.senden_frage': { en: 'This post goes out to {kanaele} now. It cannot be taken back from here.', de: 'Dieser Beitrag geht jetzt an {kanaele} hinaus. Zurückholen lässt er sich von hier aus nicht.', sq: 'Ky postim shkon tani në {kanaele}. Nga këtu nuk mund të tërhiqet.' },
  'social.unterwegs': { en: 'On its way. The history shows whether it arrived.', de: 'Unterwegs. Im Verlauf sehen Sie, ob er angekommen ist.', sq: 'Në rrugë. Te historiku shihni nëse ka mbërritur.' },
  'social.unterwegs_kurz': { en: 'Sending', de: 'Unterwegs', sq: 'Në rrugë' },
